from pathlib import Path
import json
r=json.loads(Path('RESULT.json').read_text()); payload=json.dumps(r,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CANO EPS Lab V4 | Gerçek I–V</title><style>
*{box-sizing:border-box}body{font:16px system-ui,sans-serif;background:#f1f5f7;color:#192d38;margin:0}main{max-width:1000px;margin:auto;padding:24px}header{background:#163546;color:white;padding:24px;border-radius:14px}h1{margin:0 0 8px;font-size:clamp(24px,4vw,36px)}p{line-height:1.5}.panel{background:white;padding:18px;margin-top:16px;border:1px solid #d1dce0;border-radius:12px}.row{display:flex;gap:16px;flex-wrap:wrap}.row>*{flex:1;min-width:140px}label{display:block;font-size:13px;color:#405561;margin-bottom:4px}select,button{font:inherit;border:1px solid #9bafb9;border-radius:8px;padding:10px;background:white;color:inherit;width:100%}button{cursor:pointer;background:#163546;color:white}small{color:#435864}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}.metrics div{border:1px solid #d1dce0;border-radius:8px;padding:12px}.metrics strong{display:block;font-size:24px}svg{width:100%;height:auto;display:block}.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:13px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:8px;border-bottom:1px solid #e0e7ea}th{color:#405561}footer{font-size:13px;color:#405561;margin:18px 0}a{color:#126988}@media(max-width:500px){main{padding:10px}.panel{padding:12px}header{padding:16px}}
</style><main><header><h1>CANO EPS Lab V4</h1>Gerçek ölçüm eğrileri · Fiziksel model ve referans yöntemler</header><section class="panel"><div class="row"><div><label for="device">Ölçüm cihazı</label><select id="device"><option value="RTC">RTC France</option><option value="PWP">Photowatt PWP201</option></select></div><div><label for="split">Eğitim örneklemesi</label><select id="split"><option value="alternate">Alternatif noktalar</option><option value="8">8 nokta</option><option value="10">10 nokta</option><option value="12">12 nokta</option></select></div><div><label for="export">Sonuç dosyası</label><button id="export">JSON dışa aktar</button></div></div><p id="description"></p><div class="metrics" id="metrics"></div></section><section class="panel"><h2>Akım-gerilim eğrisi</h2><svg id="plot" viewBox="0 0 700 390" role="img" aria-label="Ölçülen ve hesaplanan akım gerilim eğrisi"></svg><div class="legend"><span>● Eğitim ölçümü</span><span style="color:#ad4a18">◆ Test ölçümü</span><span style="color:#136d78">━ Fiziksel model</span><span style="color:#76629b">┄ PCHIP</span><span style="color:#78878f">┄ Doğrusal</span></div></section><section class="panel"><h2>Fiziksel parametreler</h2><div class="scroll"><table id="params"></table></div><p><small>Model parametreleri hesaplanmış tahminlerdir; doğrudan ölçülmüş dirençler ya da bağımsız sensör kalibrasyonu değildir.</small></p></section><section class="panel"><h2>Ölçüm ve tahmin</h2><div class="scroll"><table id="points"></table></div></section><footer>Kaynak: <a href="https://doi.org/10.1038/s41598-025-34584-1">Bouali ve Alamri, Scientific Reports (2026)</a>; <a href="https://github.com/Yacine-Bouali/Benchmark-Data-for-PV-Parameter-Extraction">yayıncı veri deposu</a>. İki tarihsel deneysel eğrinin eğitim dışında bırakılan noktalarıdır; yeni fiziksel cihaz veya arıza sınıflandırması değildir. Yeni CSV analizi için paket içindeki analyze_csv.py aracını kullanın.</footer></main><script>
const DATA=__DATA__;const $=id=>document.getElementById(id);const fmt=(x,n=4)=>Number(x).toLocaleString('tr-TR',{maximumFractionDigits:n,minimumFractionDigits:0});function selected(){const d=DATA.devices[$('device').value];return $('split').value==='alternate'?d:d.sparse[$('split').value]}
function draw(){const r=selected();$('description').textContent=r.train_n+' eğitim / '+r.test_n+' test noktası. Test yalnız aynı ölçüm eğrisi içinde.';$('metrics').innerHTML=[['Fiziksel RMSE',r.model.normalized_rmse_pct],['Doğrusal RMSE',r.linear.normalized_rmse_pct],['PCHIP RMSE',r.pchip.normalized_rmse_pct]].map(([k,v])=>'<div><small>'+k+'</small><strong>%'+fmt(v)+'</strong><small>Düşük değer daha iyi</small></div>').join('');let p=r.points, xmin=Math.min(...p.map(q=>q.V)),xmax=Math.max(...p.map(q=>q.V)),ymin=Math.min(...p.flatMap(q=>[q.I_A,q.pred_A,q.pchip_A,q.linear_A])),ymax=Math.max(...p.flatMap(q=>[q.I_A,q.pred_A,q.pchip_A,q.linear_A]));let X=v=>65+600*(v-xmin)/(xmax-xmin),Y=i=>330-290*(i-ymin)/(ymax-ymin);let s='';for(let j=0;j<=5;j++){let a=xmin+j*(xmax-xmin)/5,b=ymin+j*(ymax-ymin)/5;s+=`<path d="M65 ${Y(b)}H665 M${X(a)} 40V330" stroke="#d9e1e5" fill="none"/><text x="55" y="${Y(b)+4}" text-anchor="end" font-size="11">${fmt(b,2)}</text><text x="${X(a)}" y="350" text-anchor="middle" font-size="11">${fmt(a,2)}</text>`}s+='<text x="365" y="380" text-anchor="middle" font-size="13">Gerilim (V)</text><text x="16" y="180" transform="rotate(-90 16 180)" text-anchor="middle" font-size="13">Akım (A)</text>';for(let [k,c,dash] of [['linear_A','#78878f','4 4'],['pchip_A','#76629b','6 4'],['pred_A','#136d78','']]){s+='<polyline fill="none" stroke="'+c+'" stroke-width="2.5" stroke-dasharray="'+dash+'" points="'+p.map(q=>X(q.V)+','+Y(q[k])).join(' ')+'"/>'}for(let q of p){let x=X(q.V),y=Y(q.I_A);s+=q.split==='train'?`<circle cx="${x}" cy="${y}" r="3.3" fill="#192d38"/>`:`<path d="M${x} ${y-4}l4 4 -4 4 -4 -4Z" fill="#ad4a18"/>`}$('plot').innerHTML=s;$('params').innerHTML='<tr><th>Parametre</th><th>Hesaplanan değer</th></tr>'+Object.entries(r.parameters).map(([k,v])=>'<tr><td>'+k+'</td><td>'+Number(v).toPrecision(7)+'</td></tr>').join('');$('points').innerHTML='<tr><th>V</th><th>Ölçülen A</th><th>Fiziksel A</th><th>PCHIP A</th><th>Grup</th></tr>'+p.map(q=>'<tr><td>'+fmt(q.V)+'</td><td>'+fmt(q.I_A)+'</td><td>'+fmt(q.pred_A)+'</td><td>'+fmt(q.pchip_A)+'</td><td>'+(q.split==='train'?'Eğitim':'Test')+'</td></tr>').join('')}
$('device').onchange=draw;$('split').onchange=draw;$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({source:DATA.source,device:$('device').value,split:$('split').value,result:selected(),limits:DATA.limits},null,2)],{type:'application/json'}));a.download='CANO_IV_result.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};draw();</script></html>'''
Path('CANO_EPS_Lab_V4.html').write_text(page.replace('__DATA__',payload),encoding='utf-8')
